import { beforeAll, describe, expect, it } from 'bun:test'
import { createApiToken } from '@guren/core'
import app from '../src/main.js'
import { ready } from '../src/main.js'
import { User } from '../app/Models/User.js'
import { Post } from '../app/Models/Post.js'
import { migrateDatabase } from '../config/database.js'

// The production MCP endpoint: bearer-authenticated, and its two tools are the
// `posts.search` and `posts.store` routes, so validation and policy are shared.
describe('POST /mcp', () => {
  let bearer: string
  let userId: number

  const rpc = (method: string, params: unknown, token?: string) =>
    app.fetch(
      new Request('http://localhost:3333/mcp', {
        method: 'POST',
        headers: {
          'content-type': 'application/json',
          accept: 'application/json, text/event-stream',
          ...(token ? { authorization: `Bearer ${token}` } : {}),
        },
        body: JSON.stringify({ jsonrpc: '2.0', id: 1, method, params }),
      }),
    )

  beforeAll(async () => {
    await ready
    await migrateDatabase()
    const user = await User.forceCreate({
      name: 'Agent',
      email: `agent-${Date.now()}@example.com`,
      passwordHash: 'x',
    })
    userId = Number(user.id)
    const store = app.auth.getApiTokenStore()!
    bearer = (await createApiToken(store, { name: 'test', userId, abilities: ['*'] })).plainTextToken
  })

  it('refuses a call without a credential', async () => {
    expect((await rpc('tools/list', {})).status).toBe(401)
  })

  it('lists the two tools', async () => {
    const res = await rpc('tools/list', {}, bearer)
    const text = await res.text()
    expect(text).toContain('posts_search')
    expect(text).toContain('posts_store')
  })

  it('creates a post as the token user and rejects invalid input', async () => {
    const ok = await rpc('tools/call', {
      name: 'posts_store',
      arguments: { title: 'Hello MCP', excerpt: 'e', body: 'b', authorId: 999999 },
    }, bearer)
    expect(ok.status).toBe(200)
    const post = await Post.query().where('title', 'Hello MCP').first()
    expect(Number(post?.authorId)).toBe(userId)

    const before = await Post.query().count()
    const bad = await rpc('tools/call', {
      name: 'posts_store',
      arguments: { title: '', excerpt: 'e', body: 'b' },
    }, bearer)
    expect(await bad.text()).toContain('422')
    expect(await Post.query().count()).toBe(before)
  })
})
EOF
